class HashableDict(dict):
    def __hash__(self):
        return hash(
            (
                frozenset(self),
                frozenset(itervalues(self))
            )
        )


class ResourcesUsage(object):
    """
    Resources usage based on nested dict returned by get_resources_usage keyword.

    Offers methods to access parameter values based on regex matching regarding the parameter names.
    """

    def __init__(self, resources_usage, **kwargs):
        """
        Create a resource from resources usage nested dict

        :param dict resources_usage: Resources usage as returned by get_resources_usage keyword.
        """
        super(ResourcesUsage, self).__init__(**kwargs)
        self._xml = self._convert_dict_to_xml(resources_usage)
        self._xml_tree = ET.ElementTree(self._xml)

    @property
    def xml(self):
        """
        Return the XML representation of this ResourcesUsage.

        :return: XML representation of this ResourcesUsage Object
        :rtype: lxml.etree._Element
        """
        return self._xml

    @property
    def xml_string(self):
        """
        Return the dicttoxml converted XML string representation of this ResourcesUsage.

        :return: XML string representation of this ResourcesUsage
        :rtype: bytes
        """
        return self._xml_string

