    def compare_resources_usage_with_xpath(self, resources_usage1, resources_usage2, *args):

        """
        Resources usage comparison with parameter-specific user-defined checks.

        Precondition: resources_usage1 and resources_usage2 are return values from sort_resources_usage,
        i. e. they are sorted

        :param OrderedDict resources_usage1:   first resource usage dict(sorted)
        :param OrderedDict resources_usage2:   second resource usage dict(sorted)
        :param args:

            Additional arguments consist of:

            * xpath

                XPath string to the Resources Usage parameter to be checked, e.g.:

                .. code-block:: python

                    #predefined constant to select all leaf nodes
                    leaf_nodes

                    #example user-defined xpaths
                    //activeUes

                    //numOfResources

            followed by:

            * check function

                This can either be a user-defined python callable or a pre-defined constant, e. g.:

                .. code-block:: python

                    #predefined constants
                    always_true(res1, res2) #ignore resource parameters

                    equality_check(res1,res2) #check if resource parameters are equal

                    #example user-defined check functions
                    lambda x, y: x < y

                    lambda x, y: abs(int(x)-int(y)) < 4

            If an XPath specifies an XML leaf node, then the string value of its "text" is passed to the
            check function, otherwise the XML node itself.

            The order of the pairs(xpath, check_function) is relevant. After processing each resources usage
            parameter specified by an xpath, it is marked as "handled". These handled parameters will be ignored in
            later checks. This enables to pass as arguments more specific Xpaths/checks first and more general ones
            for the remaining parameters later. Certain sets of parameters can also be excluded from later checks by
            specifying them first together with the predefined check function ${Always True}.

        :return: None:  if parameter checks with user-defined check functions return True
        :raise: AssertionError: if parameter checks with user-defined check functions return False.
        """

        handled_elements = set()
        results = []
        xml1 = ET.fromstring(dicttoxml.dicttoxml(resources_usage1, attr_type=False))
        tree1 = ET.ElementTree(xml1)
        xml2 = ET.fromstring(dicttoxml.dicttoxml(resources_usage2, attr_type=False))
        tree2 = ET.ElementTree(xml2)
        for i, (xpath, func) in enumerate(
                args[i:i + 2]
                for i in range(0, len(args), 2)):
            for element1, element2 in zip_longest(
                    xml1.xpath(xpath),
                    xml2.xpath(xpath)
            ):
                valid_elements = {e for e in [element1, element2] if e is not None}
                done_elements = valid_elements & handled_elements
                handled_elements |= set(
                    sum(
                        (e.xpath("descendant-or-self::*") for e in valid_elements),
                        []
                    )
                )
                if done_elements:
                    continue
                value1 = element1.text if len(element1) == 0 else element1
                value2 = element2.text if len(element2) == 0 else element2
                if len(valid_elements) < 2 or not func(value1, value2):
                    results.append(
                        "check {i} failed for\n{element_path1}:\n{value1}\n{element_path2}:\n{value2}".format(
                            i=i,
                            element_path1=self._element_path(tree1, element1),
                            value1=self._element_value(element1),
                            element_path2=self._element_path(tree2, element2),
                            value2=self._element_value(element2)))

        if results:
            raise AssertionError("\n\n".join(results))

    @staticmethod
    def _element_path(tree, element):
        return "<no-path>" if element is None else tree.getelementpath(element)

    @staticmethod
    def _element_value(element):
        if element is None:
            return "<no-value>"
        elif len(element) == 0:
            return element.text
        else:
            return ET.tostring(element).decode("utf-8")

    @staticmethod
    def should_all_be_zero_with_xpath(resources_usage, xpath):
        """
        Check if resource usage parameters matched by a given xpath all have value zero.

        :param dict resources_usage: nested dict of resources usage as returned by get_resources_usage
        :param str xpath: xpath to match resources usage parameter values
        :return: None:  if all resources usage parameter values for paths matched by xpath equal 0
        :raise: AssertionError: if any one of the resources usage parameter values for paths
            matched by xpath is not equal to 0, all the non-zero resources are returned in the AssertionError args
        """

        resources_obj = ResourcesUsage(resources_usage)

        tree = ET.ElementTree(resources_obj.xml)

        non_zero_resources = {path: resources_obj.xpath(path)[0]
                              for path in sorted(map(tree.getelementpath, resources_obj.xml.xpath(xpath)))
                              if resources_obj.xpath(path)[0] != "0"}

        assert not non_zero_resources, non_zero_resources
